INSERT OR IGNORE INTO academy_sources (id, title, category, url, description, source_type, verified_label) VALUES
('ms-winre','Środowisko odzyskiwania Windows (WinRE)','Windows / odzyskiwanie','https://support.microsoft.com/pl-pl/windows/experience/backup-recovery/windows-recovery-environment','Oficjalny opis WinRE, naprawy rozruchu, ustawień startowych, wiersza polecenia i przywracania obrazu.','Dokumentacja','Sprawdzono 30.10.2026'),
('ms-startup-repair','Naprawa systemu podczas uruchamiania','Windows / rozruch','https://support.microsoft.com/en-us/windows/experience/startup-boot/startup-repair?nochrome=true','Procedura Microsoft Startup Repair i warunki użycia klucza BitLocker.','Dokumentacja','Strona bieżąca; sprawdzono 30.10.2026'),
('ms-sfc-dism','SFC i DISM — naprawa plików systemowych','Windows / naprawa systemu','https://support.microsoft.com/pl-pl/windows/experience/backup-recovery/using-system-file-checker-in-windows','Oficjalna kolejność DISM /RestoreHealth, a następnie sfc /scannow.','Instrukcja','Sprawdzono 30.10.2026'),
('ms-chkdsk','CHKDSK — dokumentacja polecenia','Dyski / system plików','https://learn.microsoft.com/pl-pl/windows-server/administration/windows-commands/chkdsk','Parametry CHKDSK, tryby /scan, /f, /r, ograniczenia oraz kody zakończenia. Najpierw zabezpiecz dane przy podejrzeniu awarii nośnika.','Dokumentacja','Dokumentacja Microsoft Learn; sprawdzono 30.10.2026'),
('ms-drivers','Aktualizacja i ponowna instalacja sterowników','Windows / sterowniki','https://support.microsoft.com/pl-pl/windows/aktualizowanie-sterownik%C3%B3w-za-pomoc%C4%85-mened%C5%BCera-urz%C4%85dze%C5%84-w-systemie-windows-ec62f46c-ff14-c91d-eead-d7126dc1f7b6','Microsoft opisuje Windows Update, Menedżer urządzeń, ponowną instalację i przywracanie sterownika.','Instrukcja','Sprawdzono 30.10.2026'),
('ms-bitlocker','Znajdowanie klucza odzyskiwania BitLocker','Dyski / szyfrowanie','https://support.microsoft.com/pl-pl/windows/security/encryption/find-your-bitlocker-recovery-key','Oficjalne lokalizacje klucza 48-cyfrowego: konto Microsoft, konto organizacji, wydruk lub USB. Microsoft nie może odtworzyć utraconego klucza.','Instrukcja','Sprawdzono 30.10.2026'),
('ms-install-media','Tworzenie nośnika instalacyjnego Windows','Windows / instalacja','https://support.microsoft.com/pl-pl/windows/deployment/install-upgrade/create-installation-media-for-windows','Oficjalny nośnik Windows 10/11, wymagania USB i ostrzeżenie o kopii danych przed reinstalacją.','Pobieranie / instrukcja','Sprawdzono 30.10.2026'),
('ms-backup','Kopia zapasowa, przywracanie i odzyskiwanie','Dane / kopie zapasowe','https://support.microsoft.com/pl-pl/windows/experience/backup-recovery/backup-restore-and-recovery-in-windows','Omówienie kopii zapasowej, dysku odzyskiwania i opcji przywracania.','Dokumentacja','Sprawdzono 30.10.2026'),
('ms-reset','Resetowanie komputera do ustawień początkowych','Windows / reset','https://support.microsoft.com/pl-pl/windows/experience/backup-recovery/reset-your-pc','Różnice pomiędzy zachowaniem plików, usunięciem wszystkiego i pobieraniem z chmury.','Instrukcja','Sprawdzono 30.10.2026'),
('ms-update-troubleshoot','Rozwiązywanie problemów z Windows Update','Windows / aktualizacje','https://support.microsoft.com/pl-pl/windows/deployment/updates-lifecycle/troubleshoot-problems-updating-windows','Oficjalne sposoby diagnozowania problemów z aktualizacją i kody błędów.','Instrukcja','Sprawdzono 30.10.2026'),
('ms-defender-offline','Microsoft Defender Offline — skanowanie poza Windows','Bezpieczeństwo / malware','https://learn.microsoft.com/pl-pl/defender-endpoint/microsoft-defender-offline','Skanowanie w środowisku offline; ważne ostrzeżenie o BitLocker i WinRE przed restartem.','Dokumentacja','Sprawdzono 30.10.2026'),
('ms-win11-kb','Windows 11 — KB5127648 (13.10.2026, wydanie historyczne)','Najnowsze / Windows 11','https://support.microsoft.com/pl-pl/servicing/os/windows-11/2026/10/kb5127648-windows-11-24h2-25h2-26h2-security-update','Październikowa aktualizacja zabezpieczeń z 13.10.2026. Dla Windows 11 25H2/26H2 sprawdź także nowszy podgląd KB5127936 z 28.10.2026; KB5134133 jest poprawką OOB przeznaczoną dla określonych problemów z listą CTL. Windows 11 24H2 Home/Pro zakończył aktualizacje 13.10.2026.','Biuletyn aktualizacji','Wydanie 13.10.2026; status uzupełniono 30.10.2026'),
('intel-dsa','Intel Driver & Support Assistant','Sterowniki / Intel','https://www.intel.com/content/www/us/en/support/detect.html','Oficjalne narzędzie Intel do wykrywania obsługiwanych produktów i proponowania sterowników. Na laptopach najpierw sprawdź także sterowniki OEM.','Pobieranie','Oficjalna strona pobierania; sprawdzono 30.10.2026'),
('amd-cleanup','AMD Cleanup Utility','Sterowniki / AMD','https://www.amd.com/en/resources/support-articles/faqs/GPU-601.html','Oficjalne narzędzie do usuwania sterowników grafiki AMD. Nie służy do usuwania chipset drivers.','Pobieranie / instrukcja','Ostatnia aktualizacja artykułu: 29.09.2025'),
('nvidia-clean','NVIDIA — czysta instalacja sterownika GPU','Sterowniki / NVIDIA','https://nvidia.custhelp.com/app/answers/detail/a_id/10/~/geforce-experience-driver-installation-failed.-how-do-i-manually-clean-install%20...','Instrukcja ręcznej czystej instalacji sterownika NVIDIA i typowe przyczyny niepowodzenia instalacji.','Instrukcja','Ostatnia aktualizacja artykułu: 26.05.2026'),
('asus-bios','ASUS EZ Flash — aktualizacja BIOS','BIOS / firmware','https://www.asus.com/pl/support/faq/1008859/','Oficjalny opis aktualizacji BIOS dla wybranych notebooków, AIO i MiniPC. Trzeba dobrać plik do dokładnego modelu i utrzymać zasilanie AC.','Instrukcja','Ostatnia aktualizacja: 30.04.2026'),
('hp-diag','HP PC Hardware Diagnostics UEFI','Diagnostyka / HP','https://support.hp.com/pl-pl/document/ish_3042082-2941190-16','Testy sprzętu HP uruchamiane przed Windows; procedura wejścia z menu Esc/F2 zależy od modelu.','Diagnostyka','Sprawdzono 30.10.2026'),
('dell-diag','Dell Preboot Diagnostics / SupportAssist ePSA','Diagnostyka / Dell','https://www.dell.com/support/kbdoc/en-us/000181163/how-to-enter-the-built-in-diagnostics-32-bit-diagnostics-supportassist-epsa-epsa-and-psa','Testy sprzętowe przed uruchomieniem systemu, dostępne z menu F12 w wielu urządzeniach Dell.','Diagnostyka','Sprawdzono 30.10.2026'),
('samsung-magician','Samsung Magician — diagnostyka SSD','Dyski / Samsung','https://www.samsung.com/pl/memory-storage/magician/','Oficjalne narzędzie Samsung: SMART, diagnostyka, firmware i test wydajności obsługiwanych dysków.','Pobieranie','Oficjalna strona produktu; sprawdzono 30.10.2026'),
('seatools','Seagate SeaTools — diagnostyka HDD/SSD','Dyski / Seagate','https://www.seagate.com/pl/pl/support/downloads/seatools/','Oficjalna strona SeaTools dla Windows, Linux i nośnika bootowalnego.','Pobieranie','Oficjalna strona pobierania; sprawdzono 30.10.2026'),
('memtest86plus','Memtest86+ — najnowsze wydanie v9.00','RAM / test pamięci','https://www.memtest.org/','Oficjalna strona projektu. Wyszukany wpis wersji v9.00 wskazuje wydanie 15.10.2026; przed użyciem sprawdź aktualny numer i sumy kontrolne.','Pobieranie','Wersja v9.00: 15.10.2026 (strona projektu)'),
('memtest86','PassMark MemTest86 — Free i podręcznik','RAM / test pamięci','https://www.memtest86.com/download.htm','Oficjalne wydanie MemTest86, pakiet do tworzenia nośnika UEFI i podręcznik użytkownika. Sprawdź wymagania rozruchu UEFI.','Pobieranie','Strona pobierania; sprawdzono 30.10.2026'),
('esd-principles','ESD Association — podstawy ochrony ESD','BHP / ESD','https://www.esda.org/esd-overview/esd-fundamentals/part-2-principles-of-esd-control/','Zasady wyrównywania potencjałów, uziemiania i kontrolowania ładunków elektrostatycznych.','Standard / edukacja','Sprawdzono 30.10.2026'),
('esd-procedures','ESD Association — opaski i materiały kontroli ESD','BHP / ESD','https://www.esda.org/esd-overview/esd-fundamentals/part-3-basic-esd-control-procedures-and-materials/','Praktyczne informacje o opaskach, przewodach uziemiających, stanowisku i materiałach ESD.','Standard / edukacja','Sprawdzono 30.10.2026'),
('ifixit-swollen','iFixit — postępowanie ze spuchniętą baterią','BHP / baterie','https://www.ifixit.com/Wiki/What_to_do_with_a_swollen_battery','Zasady ostrożności przy uszkodzonych i spuchniętych ogniwach litowo-jonowych. Gdy nie masz kwalifikacji, nie próbuj samodzielnego demontażu.','Poradnik bezpieczeństwa','Sprawdzono 30.10.2026'),
('hp-swollen','HP — spuchnięcie lub deformacja baterii notebooka','BHP / baterie','https://support.hp.com/hr-en/document/ish_4158581-4158704-16?fallbackLocale=us-en&requestedDocId=ish_4158577-4343460-16&validated=true','Zalecenie HP, aby przerwać używanie notebooka z wybrzuszoną baterią do czasu jej wymiany.','Instrukcja producenta','Sprawdzono 30.10.2026'),
('dell-support','Dell — sterowniki, diagnostyka i instrukcje serwisowe','Wsparcie OEM','https://www.dell.com/support/home/','Wyszukaj dokładny Service Tag lub model. Dobieraj BIOS i sterowniki do konkretnego urządzenia.','Portal producenta','Portal wsparcia producenta'),
('lenovo-support','Lenovo — wsparcie, BIOS, sterowniki i instrukcje','Wsparcie OEM','https://pcsupport.lenovo.com/','Portal wsparcia Lenovo. Wybierz dokładny model/MTM i otwórz Drivers & Software oraz Guides & Manuals.','Portal producenta','Portal wsparcia producenta'),
('acer-support','Acer — wsparcie, sterowniki i instrukcje','Wsparcie OEM','https://www.acer.com/pl-pl/support','Oficjalny portal Acer do dopasowania sterowników, BIOS i dokumentacji według modelu/SNID.','Portal producenta','Portal wsparcia producenta'),
('asus-support','ASUS — pobieranie sterowników i instrukcji','Wsparcie OEM','https://www.asus.com/pl/support/download-center/','Oficjalny portal pobierania BIOS, sterowników i podręczników według dokładnego modelu.','Portal producenta','Portal wsparcia producenta'),
('intel-pdt','Intel Processor Diagnostic Tool 4.5','CPU / diagnostyka procesora','https://www.intel.com/content/www/us/en/download/15951/intel-processor-diagnostic-tool.html','Oficjalne narzędzie Intel sprawdza identyfikację procesora, częstotliwość, funkcje i wykonuje test. Przed testem obciążeniowym sprawdź temperatury i chłodzenie.','Pobieranie / diagnostyka','Wersja 4.5; strona wskazuje wydanie 15.09.2026'),
('hwinfo','HWiNFO — monitoring sprzętu','Diagnostyka / monitoring','https://www.hwinfo.com/download/','Odczyt czujników, temperatur, taktowań, napięć i identyfikacji sprzętu. Wersja stabilna widoczna na stronie: 8.54; sprawdź licencję, ponieważ HWiNFO64/ARM64 jest freeware tylko do użytku niekomercyjnego.','Pobieranie','Strona pobierania; sprawdzono 30.10.2026'),
('cpuz','CPU-Z — identyfikacja CPU, płyty i RAM','Diagnostyka / identyfikacja','https://www.cpuid.com/softwares/cpu-z.htm','Oficjalny program CPUID pokazuje model CPU, płytę i chipset, typ pamięci, SPD, taktowania i podstawowe parametry. Nie traktuj samego odczytu jako testu stabilności.','Pobieranie','Strona bieżąca; sprawdzono 30.10.2026'),
('ms-wifi-troubleshoot','Microsoft Learn — diagnostyka problemów z Wi-Fi','Sieć / Wi-Fi','https://learn.microsoft.com/pl-pl/troubleshoot/windows-client/networking/wireless-network-connectivity-issues-troubleshooting','Podejście oparte na objawach: brak adaptera, brak listy sieci, błędy uwierzytelniania, rozłączenia i zbieranie danych diagnostycznych przed resetem.','Dokumentacja','Dokumentacja Microsoft Learn; sprawdzono 30.10.2026'),
('ms-camera-mic','Windows — kamera, mikrofon i uprawnienia prywatności','Peryferia / kamera i audio','https://support.microsoft.com/pl-pl/windows/privacy/windows-camera-microphone-and-privacy','Oficjalne ustawienia dostępu aplikacji do kamery i mikrofonu, wskaźniki użycia i kontrola uprawnień w Windows 10/11.','Instrukcja','Strona bieżąca; sprawdzono 30.10.2026'),
('uefi-spec','UEFI Forum — specyfikacje UEFI i ACPI','BIOS / standardy firmware','https://uefi.org/specifications','Oficjalne specyfikacje interfejsu UEFI i ACPI. Materiał referencyjny dla rozruchu, tablic ACPI i interfejsu firmware; nie jest instrukcją flashowania konkretnego urządzenia.','Specyfikacja','UEFI Specification 2.11; ACPI 6.6 wskazane na stronie'),
('kingston-ssd','Kingston SSD Manager','Dyski / Kingston','https://www.kingston.com/pl/support/technical/ssdmanager','Oficjalne narzędzie Kingston do identyfikacji, monitorowania kondycji i aktualizacji firmware obsługiwanych SSD. Sprawdź obsługiwany model i system; obudowy USB mogą nie być obsługiwane.','Pobieranie','Strona wskazuje Kingston SSD Manager x64 v1.5.6.5; sprawdzono 30.10.2026'),
('nvidia-drivers','NVIDIA — oficjalne sterowniki GeForce i RTX','Sterowniki / NVIDIA','https://www.nvidia.com/pl-pl/drivers/','Wyszukiwarka sterowników NVIDIA; dobierz dokładny model GPU, system, gałąź Game Ready lub Studio oraz wersję laptopową/OEM, jeśli wymaga jej producent urządzenia.','Pobieranie','Portal pobierania; sprawdzono 30.10.2026'),
('amd-chipset','AMD — instalacja sterowników chipsetu Ryzen','Sterowniki / AMD chipset','https://www.amd.com/en/resources/support-articles/faqs/CHIPSET-INSTALL.html','Oficjalna instrukcja doboru i instalacji sterowników chipsetu AMD Ryzen. Wersja pakietu oraz obsługa zależą od chipsetu i systemu; w laptopach sprawdź portal OEM.','Instrukcja','Ostatnia aktualizacja instrukcji: 10.06.2025; sprawdzono 30.10.2026'),
('router-cyber','Canadian Centre for Cyber Security — zabezpieczanie routerów','Sieć / bezpieczeństwo routera','https://www.cyber.gc.ca/en/guidance/routers-cyber-security-best-practices-itsap80019','Rządowy poradnik zabezpieczania routerów: unikalne hasła, WPA2/WPA3, aktualizacje firmware, ograniczenie zdalnego zarządzania i kontrola urządzeń w sieci.','Poradnik bezpieczeństwa','Oficjalny poradnik; sprawdzono 30.10.2026'),
('ftc-router','FTC — jak zabezpieczyć domową sieć Wi-Fi','Sieć / bezpieczeństwo routera','https://consumer.ftc.gov/articles/how-secure-your-home-wi-fi-network','Poradnik ochrony sieci Wi-Fi, szyfrowania WPA3/WPA2, zmiany danych administratora oraz kontroli konfiguracji routera.','Poradnik bezpieczeństwa','Strona bieżąca; sprawdzono 30.10.2026'),
('ms-kb5127936','Microsoft — Windows 11 KB5127936 (28.10.2026, Preview)','Windows / najnowsze aktualizacje','https://support.microsoft.com/en-us/servicing/os/windows-11/2026/10/kb5127936-windows-11-25h2-26h2-update','Zbiorcza aktualizacja w wersji Preview dla Windows 11 25H2 i 26H2. Microsoft opisuje m.in. usprawnienia BitLocker oraz znany problem wybranych urządzeń USB Audio Class 1.0 (Code 10/brak dźwięku). To podgląd — nie zalecaj jej automatycznie każdemu klientowi; sprawdź Release Health i zgodność urządzenia.','Biuletyn / Preview','Opublikowano 28.10.2026; sprawdzono 30.10.2026'),
('ms-kb5134133','Microsoft — KB5134133 (26.10.2026, poprawka OOB)','Windows / certyfikaty i aktualizacje','https://support.microsoft.com/pl-pl/servicing/os/windows-11/2026/10/kb5134133-windows-11-24h2-25h2-26h2-update','Aktualizacja poza harmonogramem dla określonych urządzeń Windows 11 24H2/25H2/26H2, które nie otrzymują aktualizacji Certificate Trust List (CTL). Nie jest to ogólne zalecenie instalacji dla wszystkich komputerów. Sprawdź, czy urządzenie należy do opisanego scenariusza.','Biuletyn / OOB','Opublikowano 26.10.2026; sprawdzono 30.10.2026'),
('ms-secureboot-cert','Microsoft Learn — aktualizacja certyfikatów Secure Boot 2023','BIOS / UEFI / Secure Boot','https://learn.microsoft.com/en-us/troubleshoot/windows-client/windows-security/update-secure-boot-certificates','Instrukcja identyfikacji i wdrażania certyfikatów Secure Boot 2023. Microsoft wskazuje stare certyfikaty z 2011 r. wygasające od czerwca 2026 r.; system może nadal uruchamiać się i otrzymywać zwykłe aktualizacje, lecz może nie uzyskać przyszłych zabezpieczeń wczesnego rozruchu. Sprawdź stan urządzenia, zdarzenia i firmware OEM.','Dokumentacja bezpieczeństwa','Sprawdzono 30.10.2026'),
('ms-release-health','Microsoft — Windows release health dashboard','Windows / najnowsze aktualizacje','https://learn.microsoft.com/en-us/windows/release-health/','Oficjalny pulpit stanu wydań Windows: znane problemy, status wdrażania, wydania i ograniczenia dla konkretnych wersji. Sprawdzaj go przed aktualizacją lub diagnozą problemu po aktualizacji.','Pulpit aktualności','Strona bieżąca; sprawdzono 30.10.2026'),
('ms-kb5127653','Microsoft — Windows 11 26H1 KB5127653 (28.10.2026, Preview)','Windows / najnowsze aktualizacje','https://support.microsoft.com/pl-pl/servicing/os/windows-11/2026/10/kb5127653-windows-11-26h1-update','Wersja Preview przeznaczona wyłącznie dla Windows 11 26H1. Opisuje m.in. poprawki obsługi BitLocker i zasilania baterii. Nie stosuj na komputerach z 24H2/25H2/26H2 — numer wersji i gałąź muszą pasować.','Biuletyn / Preview','Opublikowano 28.10.2026; sprawdzono 30.10.2026'),
('hwinfo-history','HWiNFO — historia wydań i zmiany','Diagnostyka / monitoring','https://www.hwinfo.com/version-history/','Historia wersji HWiNFO. Strona wskazuje stabilną wersję 8.54 z 30.09.2026 oraz wydanie pre-release 8.55 Build 6110. Do pracy komercyjnej sprawdź warunki licencji; freeware dotyczy użytku niekomercyjnego.','Historia wydań','Wersja stabilna 8.54 / pre-release 8.55; sprawdzono 30.10.2026'),
('ms-26h2-status','Windows 11 26H2 — bieżący stan i znane problemy','Windows / aktualizacje','https://learn.microsoft.com/windows/release-health/status-windows-11-26H2','Aktualny status wdrożenia 26H2, znane problemy i ich stan; sprawdź stronę przed diagnozą.','Dokumentacja','Sprawdzono 30.10.2026'),
('ms-26h2-release','Windows 11 — historia wydań i kompilacji','Windows / aktualizacje','https://learn.microsoft.com/en-us/windows/release-health/windows11-release-information','Oficjalne numery kompilacji i pakietów KB dla Windows 11.','Dokumentacja','Sprawdzono 30.10.2026'),
('ms-26h2-features','Co nowego w Windows 11 26H2','Windows / nowe funkcje','https://learn.microsoft.com/en-us/windows/whats-new/whats-new-windows-11-version-26h2','Nowe i ulepszone funkcje: Bluetooth LE Audio, USB4 dock, Basic Camera i aktualizacje.','Dokumentacja','Sprawdzono 30.10.2026');
